        tarp.addOrReplaceChild("tarp_side_r", CubeListBuilder.create().texOffs(184, 65).addBox(-0.3f, 0f, -6.5f, 0.6f, 9f, 13f), PartPose.offsetAndRotation(-7f, 0f, 0f, 0f, 0f, 1.012f))
