        val tarp_ropes = root.addOrReplaceChild("tarp_ropes", CubeListBuilder.create().texOffs(326, 83).addBox(-0.3f, -10.1f, -7.2f, 0.6f, 0.6f, 14.4f).texOffs(332, 159).addBox(-15.2f, -1.6f, -0.6f, 1.2f, 1.6f, 1.2f).texOffs(332, 159).addBox(14f, -1.6f, -0.6f, 1.2f, 1.6f, 1.2f), PartPose.offset(0f, 0f, 0f))
        tarp_ropes.addOrReplaceChild("tarp_rope_r", CubeListBuilder.create().texOffs(24, 162).addBox(0f, -0.25f, -0.25f, 11.477f, 0.5f, 0.5f), PartPose.offsetAndRotation(-7f, -9.8f, 0f, 1.571f, 0f, 2.295f))
        tarp_ropes.addOrReplaceChild("tarp_rope_l", CubeListBuilder.create().texOffs(24, 162).addBox(0f, -0.25f, -0.25f, 11.477f, 0.5f, 0.5f), PartPose.offsetAndRotation(7f, -9.8f, 0f, -1.571f, 0f, 0.847f))
        return LayerDefinition.create(mesh, 512, 256)
    }

    /** "rein" and "trace": straps 16 px along +y from the pivot, stretched between two points by the renderer. */
    @Suppress("LocalVariableName", "UNUSED_VARIABLE")
    fun straps(): LayerDefinition {
        val mesh = MeshDefinition()
        val root = mesh.root
        root.addOrReplaceChild("rein", CubeListBuilder.create().texOffs(508, 17).addBox(-0.35f, 0f, -0.18f, 0.7f, 16f, 0.36f), PartPose.offset(0f, 0f, 0f))
        root.addOrReplaceChild("trace", CubeListBuilder.create().texOffs(502, 17).addBox(-0.55f, 0f, -0.3f, 1.1f, 16f, 0.6f), PartPose.offset(0f, 0f, 0f))
        return LayerDefinition.create(mesh, 512, 256)
    }

